  ('deleta-skating', 'Deleta Skating', 'Pocatello, ID', '{"sections":[{"title":"First Impression and Exterior","items":[{"label":"Parking lot is clean and free of debris, garbage, weeds or hazards","type":"pass","id":"s1_1"},{"label":"Exterior lights, signage, and entry area are in good condition","type":"pass","id":"s1_2"},{"label":"Windows, doors, and front entry look clean and inviting","type":"pass","id":"s1_3"},{"label":"Promotional signs, banners, and posted information are current","type":"pass","id":"s1_4"}]},{"title":"Lobby and Front Counter","items":[{"label":"Front desk is organized and free of clutter","type":"pass","id":"s2_1"},{"label":"Prices, waivers, policies, and party info are easy to find","type":"pass","id":"s2_2"},{"label":"Guest greeting is prompt and friendly","type":"pass","id":"s2_3"},{"label":"POS systems and check-in flow are working smoothly","type":"pass","id":"s2_4"}]},{"title":"Cleanliness","items":[{"label":"Rink floor, arcade, snack area, seating, and party rooms are clean","type":"pass","id":"s3_1"},{"label":"Trash cans are emptied and tables are wiped down","type":"pass","id":"s3_2"},{"label":"Restrooms are clean, stocked, and odor free","type":"pass","id":"s3_3"},{"label":"Back-of-house and employee areas are organized","type":"pass","id":"s3_4"}]},{"title":"Skating Floor and Guest Experience","items":[{"label":"Skating surface is clean and safe","type":"pass","id":"s4_1"},{"label":"Lighting, music, sound quality, and announcements feel high energy","type":"pass","id":"s4_2"},{"label":"Floor guards/staff are visible and rules are enforced","type":"pass","id":"s4_3"},{"label":"Guest experience feels fun, smooth, and worth repeating","type":"pass","id":"s4_4"}]},{"title":"Rental Skates and Equipment","items":[{"label":"Skates are organized, clean, and available in needed sizes","type":"pass","id":"s5_1"},{"label":"Broken or worn skates are removed from use","type":"pass","id":"s5_2"},{"label":"Wheels, laces, straps, and brakes are in good condition","type":"pass","id":"s5_3"},{"label":"Fitting area, benches, and return process work well","type":"pass","id":"s5_4"}]},{"title":"Safety and Risk Management","items":[{"label":"Emergency exits and walkways are clear","type":"pass","id":"s6_1"},{"label":"First-aid kit, extinguishers, and cameras are ready and accessible","type":"pass","id":"s6_2"},{"label":"Incident log is maintained and reviewed","type":"pass","id":"s6_3"},{"label":"Unsafe behavior is addressed quickly and consistently","type":"pass","id":"s6_4"}]},{"title":"Customer Service and Staff Performance","items":[{"label":"Staff are friendly, engaged, visible, and professional","type":"pass","id":"s7_1"},{"label":"Managers are actively managing, not just present","type":"pass","id":"s7_2"},{"label":"Uniform/dress standards and punctuality expectations are met","type":"pass","id":"s7_3"},{"label":"Issues are resolved quickly without guest frustration","type":"pass","id":"s7_4"}]},{"title":"Food, Beverage, Arcade, and Revenue Drivers","items":[{"label":"Snack bar is clean, stocked, and following food-safety basics","type":"pass","id":"s8_1"},{"label":"Top-selling food and beverage items are available","type":"pass","id":"s8_2"},{"label":"Arcade/games are functioning and appealing. Note any not working","type":"pass","id":"s8_3"},{"label":"Upselling of parties, concessions, or add-ons is happening","type":"pass","id":"s8_4"}]},{"title":"Parties, Maintenance, and Marketing","items":[{"label":"Party rooms and group areas are ready for guests","type":"pass","id":"s9_1"},{"label":"Facility maintenance issues are identified and prioritized","type":"pass","id":"s9_2"},{"label":"Website, Google listing, and social media are current","type":"pass","id":"s9_3"},{"label":"In-store promotions and upcoming events are clearly visible","type":"pass","id":"s9_4"},{"label":"Every group is given an opportunity for a social media game","type":"pass","id":"s9_5"},{"label":"Every video is posted (ideally with 48hours, 1 week maximum)","type":"check","id":"s9_6"}]},{"title":"Manager Operations and Weekly Execution","items":[{"label":"Look through last week’s checklists and note anything that did not get done","type":"check","id":"s10_1"},{"label":"Talk to employees who did not finish checklists and issue strikes if needed","type":"check","id":"s10_2"},{"label":"Check up on new employees and schedule training as needed","type":"check","id":"s10_3"},{"label":"Change marquee","type":"check","id":"s10_4"},{"label":"Take inventory","type":"check","id":"s10_5"},{"label":"Order inventory","type":"check","id":"s10_6"},{"label":"Make schedule for next week","type":"check","id":"s10_7"},{"label":"Review upcoming bookings: private parties, public parties, and field trips; verify coverage","type":"check","id":"s10_8"},{"label":"Refill all arcade games and crane machines","type":"check","id":"s10_9"},{"label":"Text Brody if there are broken games","type":"check","id":"s10_10"},{"label":"Check email and flag anything that needs follow-up","type":"check","id":"s10_11"},{"label":"Check voicemails","type":"check","id":"s10_12"},{"label":"Plan upcoming theme nights if needed","type":"check","id":"s10_13"},{"label":"Recognize one employee shoutout in Square Team","type":"check","id":"s10_14"},{"label":"Print out parties for the week and order pizzas","type":"check","id":"s10_15"},{"label":"Finalize the After School Skate","type":"check","id":"s10_16"},{"label":"Update PartyWirks with special hours and events","type":"check","id":"s10_17"},{"label":"Post upcoming Facebook events in the feed section for Deleta","type":"check","id":"s10_18"},{"label":"Create and send the regular Monday marketing email in Square","type":"check","id":"s10_19"},{"label":"Schedule a second marketing email for the morning of that week’s event, if applicable","type":"check","id":"s10_20"},{"label":"Add holiday hours in Google Business and Apple Maps","type":"check","id":"s10_21"},{"label":"Empty kiosk of cash and refill cards","type":"check","id":"s10_22"},{"label":"Refill quarter machine and empty cash","type":"check","id":"s10_23"},{"label":"Make cash deposit","type":"check","id":"s10_24"},{"label":"Log kiosk sales in Square","type":"check","id":"s10_25"},{"label":"Organize redemption counter and place an order if needed","type":"check","id":"s10_26"},{"label":"Take lost and found items to the thrift store of choice","type":"check","id":"s10_27"},{"label":"Schedule shift leader meeting","type":"check","id":"s10_28"},{"label":"Fill out the extra task papers and place them at each station","type":"check","id":"s10_29"},{"label":"Send invoice to Roller Derby Team","type":"check","id":"s10_30"},{"label":"Send check to Papa Murphy’s","type":"check","id":"s10_31"}]},{"title":"Weekly summary","items":[{"label":"Top 3 strengths","type":"text","id":"s11_1"},{"label":"Top 3 issues hurting performance","type":"text","id":"s11_2"},{"label":"Would a first-time guest likely return? Why or why not?","type":"text","id":"s11_3"}]},{"title":"Action items","items":[{"id":"actions","type":"text","label":"Action items for next week — issue, owner, due date","hint":"One per line"}]}]}'::jsonb),
  ('deleta-escape-rooms', 'Deleta Escape Rooms', 'Pocatello, ID', '{"sections":[{"title":"First Impression and Exterior","items":[{"label":"Exterior signage, entry, and public-facing areas are clean, safe, and easy to understand","type":"pass","id":"s1_1"},{"label":"Hours, pricing, and booking information are accurate online","type":"pass","id":"s1_2"},{"label":"Lobby presentation matches the brand and creates anticipation before the game begins","type":"pass","id":"s1_3"},{"label":"Lobby area is clean and presentable","type":"pass","id":"s1_4"},{"label":"Any maintenance issues are identified and fixed quickly","type":"pass","id":"s1_5"}]},{"title":"Front Desk, Phones, and Guest Communication","items":[{"label":"Emails are checked regularly and answered promptly.Phone calls are answered promptly when in the office and handled with proper knowledge.","type":"pass","id":"s2_1"},{"label":"Staff arrives on time and ready to greet guests","type":"pass","id":"s2_2"},{"label":"Prepare for reservations, checking that waivers are filled out, add-ons are prepped, monthly promotions understood","type":"pass","id":"s2_3"},{"label":"Staff clearly communicates all game rules, expectations, hints, game time, and properly answers all guests questions","type":"pass","id":"s2_4"},{"label":"Guest issues are handled accordingly or escalated to management when needed. Special requirements are met at all possible times.","type":"pass","id":"s2_5"}]},{"title":"Cleanliness and Facility Presentation","items":[{"label":"Lobby, escape rooms, and office area are consistently clean and clutter-free","type":"pass","id":"s3_1"},{"label":"Trash is removed immediately and trash cans are taken out once a week unless there is food, then immediately","type":"pass","id":"s3_2"},{"label":"Lighting, sound, props, and thematic decor are in good condition and reported to management if it needs fixed","type":"pass","id":"s3_3"},{"label":"Storage areas are clean and accessible","type":"pass","id":"s3_4"},{"label":"Any damaged props, furniture, or fixtures are removed, repaired, or reported to management","type":"pass","id":"s3_5"}]},{"title":"Booking Flow, Parties, and Group Execution","items":[{"label":"Upcoming bookings for the next day are reviewed and staffing coverage is confirmed","type":"pass","id":"s4_1"},{"label":"Escape rooms are fully reset, clean, and in proper working order before groups arrive","type":"pass","id":"s4_2"},{"label":"Waivers, add-ons, and timing for groups are confirmed in advance","type":"pass","id":"s4_3"},{"label":"Front desk and game masters know the schedule, if the group needs to pay, add-ons, and any special notes","type":"pass","id":"s4_4"},{"label":"Groups move through check-in, gameplay, photos, and exit without confusion","type":"pass","id":"s4_5"}]},{"title":"Escape Room Readiness and Reset Quality","items":[{"label":"Every room is fully reset, clean, and ready before the next group starts","type":"pass","id":"s5_1"},{"label":"Reset checklists are followed and completed with consistency","type":"pass","id":"s5_2"},{"label":"Locks, sensors, triggers, magnets, cameras, and sound are tested and functioning at the start of the shift","type":"pass","id":"s5_3"},{"label":"Flashlights, batteries, and replacement items are stocked and easy for staff to access","type":"pass","id":"s5_4"},{"label":"Any room with a known issue is documented immediately and either fixed or removed from sale","type":"pass","id":"s5_5"}]},{"title":"Game Mastering and Clue Delivery","items":[{"label":"Game masters explain rules, story, hint and time expectations clearly and thoroughly. Ask if there are any questions throughout this process","type":"pass","id":"s6_1"},{"label":"Staff monitor games attentively and intervene at the right moments","type":"pass","id":"s6_2"},{"label":"Clues are delivered in a way that supports fun without giving away too much too early","type":"pass","id":"s6_3"},{"label":"Staff stay in character or on-brand when appropriate for the room experience","type":"pass","id":"s6_4"},{"label":"Escalations, stuck groups, and technical issues are handled calmly and quickly","type":"pass","id":"s6_5"}]},{"title":"Safety, Security, and Risk Control","items":[{"label":"Emergency exits, paths of travel, and safety equipment remain accessible","type":"pass","id":"s7_1"},{"label":"Cameras are working as expected","type":"pass","id":"s7_2"},{"label":"Staff know what to do for injury, evacuation, guest conflict, or equipment failure","type":"pass","id":"s7_3"},{"label":"Trip hazards, broken furniture, exposed wires, or unsafe props are corrected immediately","type":"pass","id":"s7_4"},{"label":"Incident reports, refunds, and serious guest concerns are documented clearly and communicated to management","type":"pass","id":"s7_5"}]},{"title":"Staff Training, Scheduling, and Accountability","items":[{"label":"New staff are trained on check-in, room reset, clue standards, and guest communication","type":"pass","id":"s8_1"},{"label":"Managers coach staff quickly when standards slip instead of letting problems repeat","type":"pass","id":"s8_2"},{"label":"Uniforms, appearance, and professionalism match brand expectations","type":"pass","id":"s8_3"},{"label":"Employee wins, misses, and follow-up items are documented and addressed weekly","type":"pass","id":"s8_4"}]},{"title":"Sales, Revenue Capture, and Follow-Through","items":[{"label":"Add-ons and future bookings are explained when appropriate","type":"pass","id":"s9_1"},{"label":"Discounts, refunds, and comps are used appropriately and done by management","type":"pass","id":"s9_2"},{"label":"POS system, waivers, and booking platform are working correctly and reconciled as needed","type":"pass","id":"s9_3"}]},{"title":"Marketing, Reviews, and Guest Invitation Standards","items":[{"label":"Every group is invited to play a social media game","type":"pass","id":"s10_1"},{"label":"Upcoming events, promotions, and room highlights are being shared consistently","type":"pass","id":"s10_2"},{"label":"Google profile, website details, and social pages show accurate hours and current offers","type":"pass","id":"s10_3"},{"label":"Recent reviews are monitored and responded to appropriately","type":"pass","id":"s10_4"},{"label":"Staff invite happy guests to leave reviews and mention future room experiences","type":"pass","id":"s10_5"},{"label":"Staff inform all guests to follow any and all social media platforms for fun videos and daily updates","type":"pass","id":"s10_6"},{"label":"Posts are planned for the week, videos and pictures are taken according, and posts are pre-scheduled when available","type":"pass","id":"s10_7"},{"label":"Comments and messages on social media are answered promptly and appropriately.","type":"pass","id":"s10_8"},{"label":"Employees are liking, commenting, and engaging with social media posts to up engagement to boost posts.","type":"pass","id":"s10_9"}]},{"title":"Weekly Manager Follow-Through","items":[{"label":"Weekly checklist issues from the prior week were reviewed and corrected","type":"pass","id":"s11_1"},{"label":"Any unresolved maintenance, room issues, or staff problems were followed up on","type":"pass","id":"s11_2"},{"label":"Inventory room-reset supplies was checked and reordered as needed","type":"pass","id":"s11_3"},{"label":"Important emails, notices, bookings, or operational updates were handled appropriately","type":"pass","id":"s11_4"},{"label":"Top 3 action items for next week are clear and assigned","type":"pass","id":"s11_5"}]},{"title":"Weekly Summary","items":[{"label":"Top strengths this week","type":"text","id":"s12_1"},{"label":"Top issues needing correction","type":"text","id":"s12_2"},{"label":"Highest-priority fix for next week","type":"text","id":"s12_3"},{"label":"Person responsible","type":"text","id":"s12_4"},{"label":"Target completion date","type":"text","id":"s12_5"}]}]}'::jsonb),
